  --od-line:#e1e8f1;
  --od-brand:#365eda;
  --od-paper:#fff;
  --od-bg:#f5f7fb;
  --od-input-border:#7f8da1;
  --od-accent-ink:var(--od-brand);
  --od-focus:var(--od-brand);
  --od-warning:#80510d;
  --od-muted:#f5f7fb;
  --od-positive:#117a5d;
  --od-negative:#ae3d4b;
