:root{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC",system-ui,sans-serif;font-size:13px;line-height:1.45;color:var(--od-ink);background:var(--od-bg);color-scheme:light}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{display:flex;flex-direction:column;margin:0;background:var(--od-bg)}
input,select,textarea{width:100%;min-width:0;border:1px solid var(--od-input-border);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font:inherit;padding:var(--space-2) var(--space-3)}
input,select{min-height:36px}
input[type=checkbox]{width:auto;min-height:0;margin-right:6px}
textarea{display:block;margin:var(--space-2) 0 var(--space-3);font:var(--od-note-size)/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;resize:vertical;tab-size:2}
button{max-width:100%;border:0;border-radius:var(--radius-control);background:var(--od-brand);color:var(--od-on-brand);padding:var(--space-2) var(--space-3);min-height:34px;font:inherit;cursor:pointer;overflow-wrap:anywhere}
button:disabled{opacity:.48;cursor:not-allowed}
button:hover:not(:disabled){filter:brightness(.97)}
:focus-visible{outline:2px solid var(--od-focus);outline-offset:2px}
@media(prefers-color-scheme:dark){
  :root{color-scheme:dark}}
/* Shared primitives: semantics here; state-specific geometry stays in tool-shell.css. */
.od-page{min-width:0}
.od-toolbar{display:flex;align-items:center;gap:var(--space-2);min-width:0}
.od-page-head{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);min-height:var(--od-icon-size);min-width:0}
.od-page-title{min-width:0;margin:0;color:var(--od-ink);font-size:var(--od-note-size);font-weight:600;line-height:1.5;overflow-wrap:anywhere}
.od-page-actions{display:flex;align-items:center;justify-content:flex-end;gap:var(--space-2);min-width:0;flex:none;margin-inline-start:auto}
/* Tools Index/Detail is the trusted Tab header baseline; narrow actions wrap as a group. */
@media(max-width:240px){.od-page-head{flex-wrap:wrap}.od-page-actions{flex-wrap:wrap;max-width:100%}}
.od-stack{display:grid;gap:var(--space-2);min-width:0}
/* Public component contract: semantic appearance lives only here; pages own layout. */
.od-surface{min-width:0;background:var(--od-paper);border:1px solid var(--od-line);border-radius:var(--radius-surface)}
.od-surface--padded{padding:var(--space-3)}
.od-button{display:inline-flex;align-items:center;justify-content:center;gap:var(--space-1);max-width:100%;min-height:36px;padding:var(--space-2) var(--space-3);font:inherit;font-weight:650;border:1px solid var(--od-brand);border-radius:var(--radius-control);background:var(--od-brand);color:var(--od-on-brand);text-align:center}
.od-button--secondary{background:var(--od-action-bg);border-color:var(--od-action-border);color:var(--od-action-ink)}
.od-button--danger{background:var(--od-negative-bg);border-color:var(--od-negative);color:var(--od-negative)}
.od-button--quiet{background:transparent;border-color:transparent;color:var(--od-ink)}
.od-icon-button{position:relative;display:inline-grid;place-items:center;flex:none;width:var(--od-icon-size);height:var(--od-icon-size);min-width:var(--od-icon-size);min-height:var(--od-icon-size);padding:0;border:1px solid var(--od-line);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-sub)}
.od-icon-button--primary{border-color:var(--od-brand);background:var(--od-brand);color:var(--od-on-brand)}
.od-icon-button--danger{border-color:var(--od-negative);background:var(--od-negative-bg);color:var(--od-negative)}
.od-icon-button svg{width:18px;height:18px;display:block;pointer-events:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.od-icon-button:hover:not(:disabled):not(.od-icon-button--primary):not(.od-icon-button--danger){background:var(--od-muted)}
.od-icon-button[aria-expanded=true]{background:var(--od-muted);border-color:var(--od-focus);color:var(--od-accent-ink)}
:is(input,select,textarea).od-field{min-width:0;border:1px solid var(--od-input-border);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font-size:var(--od-body-size)}
:is(input,select,textarea).od-field:disabled,
:is(input,textarea).od-field[readonly]{background:var(--od-muted);color:var(--od-sub)}
:is(input,select,textarea).od-field[aria-invalid="true"]{border-color:var(--od-negative)}
.od-form-field{display:grid;gap:var(--space-1);min-width:0}
.od-field-label{margin:0;font-size:var(--od-note-size);font-weight:650;line-height:1.5;color:var(--od-ink)}
.od-field-help{margin:0;font-size:var(--od-note-size);line-height:1.55;color:var(--od-sub)}
.od-field-error{margin:0;font-size:var(--od-note-size);line-height:1.55;color:var(--od-negative)}
.od-body{color:var(--od-ink);font-size:var(--od-body-size);line-height:1.55;font-weight:400}
.od-note{color:var(--od-sub);font-size:var(--od-note-size);line-height:1.55;font-weight:400}
.od-title{color:var(--od-ink);font-size:var(--od-body-size);line-height:1.5;font-weight:650}
.od-technical{font-size:var(--od-meta-size);line-height:1.55;color:var(--od-sub);font-weight:400;overflow-wrap:anywhere}
.od-result{min-width:0;margin:0;border:1px solid var(--od-line);background:var(--od-muted);border-radius:var(--radius-control);padding:var(--space-2);color:var(--od-ink)}
.od-alert{margin:0;padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-control);color:var(--od-ink);background:var(--od-muted)}
.od-alert--warning{background:var(--od-warning-bg);border-color:var(--od-warning-border);color:var(--od-warning-ink)}
.od-alert--error{background:var(--od-negative-bg);border-color:var(--od-negative);color:var(--od-negative)}
.od-disclosure{min-width:0;margin:0;border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-paper);color:var(--od-ink)}
/* All trusted disclosures use the same centered header, marker and type scale.
 * Keep the lighter --flat and emphasis-only --info variants on this one component. */
.od-disclosure>summary{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2);min-height:44px;padding:var(--space-2) var(--space-3);list-style:none;cursor:pointer;font-size:var(--od-body-size);line-height:1.5;font-weight:650;color:var(--od-ink);overflow-wrap:anywhere}
.od-disclosure>summary::-webkit-details-marker{display:none}
.od-disclosure>summary::before{content:"";flex:none;width:7px;height:7px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(-45deg)}
.od-disclosure[open]>summary::before{transform:rotate(45deg)}
.od-disclosure>summary>*{min-width:0}
.od-disclosure>summary>span:only-child{flex:1 1 0}
.od-disclosure>summary :is(strong,b){font-size:inherit;font-weight:inherit;color:inherit}
.od-disclosure[open]>summary{border-bottom:1px solid var(--od-line)}
/* One hover contract for every trusted first-level disclosure. */
.od-disclosure>summary:hover{background:var(--od-muted)}
.od-disclosure:not([open])>summary:hover{border-radius:var(--radius-surface)}
.od-disclosure[open]>summary:hover{border-radius:var(--radius-surface) var(--radius-surface) 0 0}
/** Allow 100%-width form fields inside a disclosure without their 12px margins
 * pushing their right edge outside a narrow Side Panel. */
.od-disclosure>:not(summary){min-width:0;max-width:calc(100% - var(--space-3) - var(--space-3));margin:var(--space-2) var(--space-3) 0}
.od-disclosure>:last-child:not(summary){margin-bottom:var(--space-3)}
.od-disclosure--info>summary{color:var(--od-brand)}
.od-disclosure--info[open]>summary{background:var(--od-muted)}
.od-disclosure--flat{border:0;border-radius:0;background:transparent}
.od-disclosure--flat>summary{min-height:36px;padding:var(--space-2) 0;font-size:var(--od-note-size);color:var(--od-sub)}
.od-disclosure--flat[open]>summary{border-bottom:1px solid var(--od-line);background:transparent}
.od-disclosure--flat>:not(summary){max-width:100%;margin:var(--space-2) 0 0}
.od-disclosure--flat>:last-child:not(summary){margin-bottom:0}
/* Technical disclosures stay frameless, including hover treatment. */
.od-disclosure--flat:is(:not([open]),[open])>summary:hover{background:var(--od-muted);border-radius:var(--radius-control)}
.od-segmented{display:flex;width:max-content;max-width:100%;gap:2px;padding:3px;background:var(--od-muted);border:1px solid var(--od-input-border);border-radius:var(--radius-surface)}
.od-segmented>button{min-height:32px;border-radius:var(--radius-control)}

/* Collapsible rows are interactive controls, including nested technical details. */
@media(pointer:coarse){.od-disclosure>summary{min-height:44px}}

/* Only layout and product-specific surfaces; core control appearances come from shared OpenDesk CSS. */
.ps{width:100%;min-width:0;min-height:100vh;background:var(--od-paper);display:grid;align-content:start;gap:var(--space-3);padding:var(--space-3);color:var(--od-ink)}
.ps-head{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--space-2);margin-bottom:var(--space-3)}
.ps-head>div{min-width:0}.ps-head h2,.ps-form-head h2{margin:0;font-size:17px;line-height:1.35}
.ps-head p{margin:var(--space-1) 0 0;font-size:var(--od-meta-size);overflow-wrap:anywhere}.ps-head .od-button{flex:none}
.ps-section-heading{display:flex;align-items:baseline;justify-content:space-between;gap:var(--space-2);margin:var(--space-4) 0 var(--space-2)}
.ps-section-heading h3{font-size:var(--od-note-size);margin:0;line-height:1.5}.ps-section-heading small{font-size:var(--od-meta-size);color:var(--od-sub)}
.ps-list{display:grid;gap:var(--space-2)}
.ps-card{padding:10px;border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-paper)}
.ps-glyph{width:36px;height:36px;border:1px solid var(--od-line);background:var(--od-bg);border-radius:10px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:2px;line-height:1.05;font-weight:750;font-size:11px;flex:none;overflow:hidden}
.ps-card-actions{display:flex;gap:var(--space-1);align-items:center;margin:0}
.ps-card-actions .od-button,.ps-more .od-button{min-width:0;min-height:32px}
.ps-more{display:flex;justify-content:flex-end;gap:var(--space-1);flex-wrap:wrap;margin-top:var(--space-2);border-top:1px solid var(--od-line);padding-top:var(--space-2)}
.ps-confirm{margin-top:var(--space-2);padding:var(--space-3);background:var(--od-negative-bg);border-radius:var(--radius-control);font-size:var(--od-meta-size)}.ps-confirm p{margin:0 0 var(--space-2)}
.ps-empty{border:1px dashed var(--od-line);border-radius:var(--radius-surface);text-align:center;padding:24px var(--space-3);color:var(--od-sub)}
.ps-empty strong{font-size:var(--od-body-size);color:var(--od-ink)}.ps-empty p{font-size:var(--od-meta-size);margin:var(--space-1) 0 0}
.ps-hint{font-size:var(--od-meta-size);line-height:1.5;color:var(--od-sub);margin:var(--space-1) 0 var(--space-2);overflow-wrap:anywhere}
.ps-settings{display:grid;gap:var(--space-2);margin-top:var(--space-2)}.ps-settings .ps-section-heading{margin-bottom:0}
.ps-setting-card{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);padding:var(--space-3);min-height:58px;cursor:pointer;margin:0}
.ps-setting-copy{min-width:0}.ps-setting-copy strong,.ps-setting-copy small{display:block}.ps-setting-copy strong{font-size:var(--od-note-size)}
.ps-setting-copy small{font-size:var(--od-meta-size);color:var(--od-sub);margin-top:var(--space-1);line-height:1.4}
.ps-switch{display:grid;place-items:center;position:relative;flex:none;width:40px;height:36px}
.ps-switch input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer;z-index:1}
.ps-switch-track{width:36px;height:22px;background:var(--od-input-border);border-radius:var(--radius-pill);position:relative;pointer-events:none}
.ps-switch-track:after{content:"";position:absolute;left:3px;top:3px;width:16px;height:16px;background:var(--od-paper);border-radius:50%;box-shadow:0 1px 3px var(--od-line)}
.ps-switch input:checked+.ps-switch-track{background:var(--od-brand)}.ps-switch input:checked+.ps-switch-track:after{transform:translateX(14px)}
.ps-switch input:focus-visible+.ps-switch-track{outline:3px solid var(--od-focus);outline-offset:3px}
.ps-permission-strip small{color:var(--od-sub);margin-top:var(--space-1)}
.ps-form-head{display:flex;align-items:center;gap:var(--space-2);margin-bottom:var(--space-4)}
.ps-primary{padding:var(--space-2) 0;background:transparent;border:0;margin-bottom:var(--space-2)}
.ps-primary textarea{width:100%;height:88px;min-height:88px;max-height:88px;resize:none;overflow-y:auto;overflow-wrap:anywhere;background:var(--od-paper);font-size:var(--od-body-size);font-family:inherit;line-height:1.55}
.ps-required{color:var(--od-accent-ink);font-size:var(--od-meta-size)}
.ps-quota{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);font-size:var(--od-meta-size);color:var(--od-sub)}
.ps-quota[data-error="true"]{color:var(--od-negative)}
.ps-optional{padding:var(--space-2);display:grid;gap:var(--space-2)}
.ps-optional-head{display:flex;justify-content:space-between;align-items:baseline;gap:var(--space-2)}
.ps-optional-head h3{font-size:var(--od-note-size);margin:0}.ps-optional-head small{font-size:var(--od-meta-size);color:var(--od-sub)}
.ps-optional input.od-field{width:100%;min-width:0}
.ps-optional .od-field-label{margin-bottom:0}.ps-optional .ps-hint{margin:0 0 var(--space-1)}
.ps-effective-preview{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2);padding:var(--space-2) var(--space-3);background:var(--od-bg);border-radius:var(--radius-control);font-size:var(--od-meta-size);color:var(--od-sub);overflow-wrap:anywhere}
.ps-effective-preview strong{font-size:var(--od-note-size);color:var(--od-ink)}
.ps-preview-glyph{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:2px;min-width:32px;height:32px;border:1px solid var(--od-line);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font-weight:700}
.ps-enabled{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);padding:var(--space-2);margin:0;font-size:var(--od-meta-size)}
.ps-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:var(--space-2);margin-top:var(--space-3)}
.ps-confirm .ps-actions{justify-content:flex-start}
.ps-error,.ps-warning{padding:var(--space-3);margin:var(--space-3) 0;border-radius:var(--radius-control);overflow-wrap:anywhere;font-size:var(--od-meta-size)}
.ps-error{color:var(--od-negative);background:var(--od-negative-bg)}.ps-warning{background:var(--od-warning-bg);color:var(--od-warning-ink)}.ps-warning p{margin:var(--space-1) 0}
.ps-copy{padding:var(--space-3);margin-top:var(--space-3)}.ps-copy textarea{width:100%;min-height:110px;resize:vertical;white-space:pre-wrap}
.ps-status{font-size:var(--od-meta-size);padding:var(--space-3);background:var(--od-bg);color:var(--od-sub);border-radius:var(--radius-control);overflow-wrap:anywhere;margin:0}
.ps-status[data-error="true"]{background:var(--od-negative-bg);color:var(--od-negative)}
@media(max-width:340px){.ps-head{flex-wrap:wrap}.ps-card-main{grid-template-columns:34px minmax(0,1fr) auto;gap:var(--space-1)}.ps-card{padding:var(--space-2)}}

/* R1.13: content-first cards and compact form layout. */
.ps{gap:var(--space-2);padding:var(--space-2) var(--space-3)}
.ps-head{align-items:center;margin:0 0 var(--space-1)}
.ps-head h2,.ps-form-head h2{font-size:15px}
.ps-list-caption{display:flex;justify-content:space-between;gap:var(--space-2);align-items:baseline;flex-wrap:wrap;color:var(--od-sub);font-size:var(--od-meta-size);margin:0 0 var(--space-1)}
.ps-list-caption small{font-size:var(--od-meta-size);white-space:nowrap}
.ps-card{display:grid;gap:7px;padding:8px}
.ps-card-use{width:100%;min-width:0;min-height:36px;justify-content:flex-start;text-align:left}
.ps-card-preview{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;white-space:pre-wrap;word-break:break-word;max-width:100%;font-size:var(--od-body-size);font-weight:540;line-height:1.55}
.ps-card-use:disabled{cursor:default}
.ps-card-meta{display:flex;align-items:center;gap:var(--space-2);min-width:0}
.ps-glyph{width:30px;height:30px;min-width:30px;font-size:10px;border-radius:9px}
.ps-info-name{min-width:0;flex:1;color:var(--od-sub);font-size:var(--od-meta-size);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-card-actions{margin-left:auto;gap:2px}
.ps-card-actions .od-button{min-height:28px;min-width:28px}
.ps-card.is-disabled .ps-card-use{color:var(--od-sub)}
.ps-compact-row{display:grid;grid-template-columns:80px minmax(0,1fr);align-items:center;gap:var(--space-2)}
.ps-compact-row .od-field-label{font-size:var(--od-meta-size)}
.ps-compact-row .od-field{height:34px;min-height:34px;margin:0}
.ps-optional .ps-hint{margin:0}
.ps-form-head{margin-bottom:var(--space-2)}
.ps-effective-preview{padding:7px 8px;gap:6px}
.ps-enabled{padding:7px 8px}
@media(max-width:340px){.ps-compact-row{grid-template-columns:70px minmax(0,1fr)}}

/* R1.13 native form/list closure: icon + body + actions in one compact row. */
.ps-card-main{display:grid;grid-template-columns:30px minmax(0,1fr) auto;align-items:center;gap:var(--space-2);min-width:0}
.ps-card-use{padding:4px 0;border:0;overflow:hidden;max-width:100%}
.ps-card-caption{color:var(--od-sub);font-size:var(--od-meta-size);padding-left:calc(30px + var(--space-2));overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ps-optional-head{width:100%;padding:2px 0;text-align:left;border:0;background:transparent;color:var(--od-ink);font:inherit;cursor:pointer}
.ps-optional-head>span{font-size:var(--od-note-size);font-weight:650}
.ps-optional-head:focus-visible{outline:3px solid var(--od-focus);outline-offset:2px}
.ps-setting-fields{display:grid;gap:var(--space-2)}
.ps-setting-fields[hidden]{display:none}
.ps-effective-preview{margin-bottom:var(--space-2)}
.ps-inline-error{color:var(--od-negative);font-size:var(--od-meta-size);margin:var(--space-1) 0}
.ps-clipboard-buffer{position:fixed;left:-10000px;top:-10000px;width:1px;height:1px;opacity:0;pointer-events:none}
@media(max-width:340px){.ps-card-main{grid-template-columns:30px minmax(0,1fr) auto;gap:var(--space-1)}}

/* R2 website chooser: two primary targets, advanced path collapsed. */
.ps-sites{display:grid;gap:var(--space-2);border-top:1px solid var(--od-line);padding-top:var(--space-2);margin-top:var(--space-2)}
.ps-sites-heading{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2)}
.ps-sites-heading h3{margin:0;font-size:var(--od-note-size)}
.ps-sites-panel,.ps-sites-list{display:grid;gap:var(--space-2)}
#ps-sites-panel[hidden],#ps-site-form[hidden]{display:none}
#ps-sites-panel{display:grid;gap:var(--space-2)}
.ps-sites-list{min-width:0}
.ps-site-row{display:grid;gap:var(--space-1);border:1px solid var(--od-line);padding:var(--space-2);border-radius:var(--radius-control)}
.ps-site-row-heading{display:flex;justify-content:space-between;align-items:center;gap:var(--space-2);font-size:var(--od-note-size);overflow-wrap:anywhere}
.ps-site-row .ps-actions{margin-top:0}
.ps-site-form{display:grid;gap:var(--space-2);padding:var(--space-3);min-width:0}
.ps-site-form .ps-compact-row{grid-template-columns:80px minmax(0,1fr)}
.ps-site-form input.od-field{width:100%;min-width:0}
.ps-site-form>button{justify-self:start}
.ps-site-form .ps-actions{margin:0}
.ps-site-origin{margin:0;color:var(--od-sub);font-size:var(--od-meta-size);overflow-wrap:anywhere}
.ps-site-advanced summary{font-size:var(--od-meta-size);cursor:pointer;color:var(--od-sub)}
.ps-site-advanced .ps-compact-row{margin-top:var(--space-2)}
#ps-site-status[data-error="true"]{background:var(--od-negative-bg);color:var(--od-negative)}
@media(max-width:340px){.ps-site-form .ps-compact-row{grid-template-columns:70px minmax(0,1fr)}}

js:
(() => {
'use strict';
const {root,request,setState}=globalThis.OpenDeskTool;
const model=globalThis.OpenDeskPromptShortcutsModel,el=id=>root.querySelector('#'+id);
const dom=(tag,cls='',text='')=>{const n=root.ownerDocument.createElement(tag);n.className=cls;n.textContent=text;return n;};
const KEY='library',MENU_ACTION='add-selection';
let data=model.defaults(),etag=null,ready=false,busy=false,dirty=false,mode='index',editId=null;
let baseline='',expanded=null,pendingDelete=null,pendingLeave=null,unconfirmedWrite=false;
const SITE_KEY='sites';
let sites=model.sitesDefaults(),sitesEtag=null,sitesReady=false,siteBusy=false,siteDirty=false;
let siteOrigin=null,siteEditing=null,siteBaseline='',siteVerified=null,siteDelete=null;
let sitePoll=0,siteSession=null,siteEpoch=0,siteDiscardPending=false;
function report(){setState({dirty:dirty||siteDirty,busy:busy||siteBusy});}
function status(message='',isError=false){const n=el('ps-status');n.textContent=message;n.hidden=!message;n.dataset.error=String(isError);}
function error(message=''){el('ps-error').textContent=message;el('ps-error').hidden=!message;}
function bodyError(message=''){el('ps-body-error').textContent=message;el('ps-body-error').hidden=!message;}
function options(open){
  el('ps-setting-fields').hidden=!open;
  el('ps-toggle-settings').setAttribute('aria-expanded',String(open));
  el('ps-toggle-caret').textContent=open?'收起':'展开';
}
function form(){
  const previous=editId?data.items.find(item=>item.id===editId):null;
  return {body:el('ps-body').value,label:el('ps-label').value,name:el('ps-name').value,
    shape:previous?.shape==='round'?'round':'square',enabled:el('ps-enabled').checked};
}
function projected(){
  const draft=form(),old=editId?data.items.find(row=>row.id===editId):null;
  if(!draft.body.trim())return null;
  try{
    const row=model.draft(draft,old,()=> '00000000-0000-4000-8000-000000000000');
    return model.load({...data,items:old?data.items.map(item=>item.id===old.id?row:item):
      [...data.items,{...row,order:data.items.length}]});
  }catch{return null;}
}
function preview(){
  const draft=form(),fallback=model.auto(draft.body),label=draft.label.trim()||fallback;
  const glyph=el('ps-preview-glyph');
  glyph.replaceChildren(...model.parts(label||'—').map(char=>dom('span','',char)));
  el('ps-preview-name').textContent=draft.name.trim()||fallback||'待生成';
  const estimate=projected(),bytes=estimate?model.bytes(estimate):null;
  el('ps-quota-value').textContent=(bytes===null?'—':bytes)+' / 8192 B';
  el('ps-quota').dataset.error=String(bytes!==null&&bytes>8192);
}
function changed(){
  if(mode!=='form')return;
  dirty=JSON.stringify(form())!==baseline;if(el('ps-body').value.trim())bodyError('');preview();report();
}
function lock(){
  for(const id of ['ps-new','ps-save','ps-web'])
    el(id).disabled=!ready||busy||unconfirmedWrite;
  for(const id of ['ps-cancel','ps-discard'])el(id).disabled=busy;
  el('ps-form').setAttribute('aria-busy',String(busy));
  el('ps-save').textContent=busy?'保存中…':'保存提示词';
  for(const b of el('ps-list').querySelectorAll('button'))b.disabled=!ready||busy||unconfirmedWrite||b.dataset.locked==='1';
  report();
}
function index(){
  mode='index';editId=null;dirty=false;pendingLeave=null;pendingDelete=null;
  el('ps-index').hidden=false;el('ps-edit').hidden=true;el('ps-leave').hidden=true;
  error('');bodyError('');render();report();
}
function back(callback=index){
  if(busy)return;
  if(!dirty){callback();return;}
  pendingLeave=callback;el('ps-leave').hidden=false;el('ps-stay').focus();
}
function start(id=null,preset=''){
  if(!ready||busy||unconfirmedWrite)return;
  const row=id?data.items.find(item=>item.id===id):null;
  if(id&&!row){status('原条目已变化，请重新打开工具核对。',true);return;}
  mode='form';editId=id;el('ps-index').hidden=true;el('ps-edit').hidden=false;
  el('ps-form-title').textContent=id?'编辑提示词':'新建提示词';
  el('ps-body').value=row?.body??preset;
  el('ps-label').value=row&&!row.labelAuto?row.label:'';
  el('ps-name').value=row&&!row.nameAuto?row.name:'';
  el('ps-enabled').checked=row?.enabled!==false;error('');bodyError('');options(true);el('ps-leave').hidden=true;
  // A native-menu selection is an unsaved new draft, never an acknowledged baseline.
  baseline=JSON.stringify({...form(),body:row?.body??''});changed();el('ps-body').focus();
}
function button(parent,text,callback,variant='secondary'){
  const b=dom('button','od-button od-button--'+variant,text);b.type='button';
  b.addEventListener('click',callback);parent.append(b);return b;
}

function siteMessage(text='',isError=false){
  const n=el('ps-site-status');n.textContent=text;n.hidden=!text;n.dataset.error=String(isError);
}
function siteKey(row){return row.origin+'|'+row.pathScope;}
function siteDraft(){
  return {origin:siteOrigin,pathScope:el('ps-site-path').value||'/',
    containerSelector:el('ps-site-container').value,editorSelector:el('ps-site-editor').value,
    enabled:el('ps-site-enabled').checked};
}
function invalidateSite(){
  siteVerified=null;el('ps-site-verified').textContent='两个目标发生变化，请重新测试。';
  siteDirty=Boolean(siteOrigin&&JSON.stringify(siteDraft())!==siteBaseline);
  siteDiscardPending=false;report();
}
async function readSites(){
  const saved=await request('storage.get',{key:SITE_KEY,withEtag:true});
  if(!/^[a-f0-9]{64}$/.test(saved?.etag||'')||!Object.hasOwn(saved,'value'))
    throw Error('没有收到网站规则的可验证存储版本');
  return {data:model.sitesLoad(saved.value),etag:saved.etag};
}
async function loadSites(){
  const result=await readSites();sites=result.data;sitesEtag=result.etag;sitesReady=true;
  renderSites();return sites;
}
async function commitSites(next){
  if(!sitesReady||siteBusy||!sitesEtag)throw Error('网站规则尚未就绪');
  const normalized=model.sitesLoad(next);
  if(model.bytes(normalized)>8192)throw Error('网站适配规则超出 8 KiB');
  siteBusy=true;report();
  try{
    let reply;
    try{
      reply=await request('storage.set',{key:SITE_KEY,value:normalized,ifMatch:sitesEtag});
      if(reply?.saved!==true||!/^[a-f0-9]{64}$/.test(reply.etag||''))
        throw Error('保存回执不完整');
    }catch(error){
      if(['E_STORAGE_CONFLICT','E_TOOL_DATA_LIMIT'].includes(error?.code))throw error;
      // Unknown outcome: read back the exact canonical rule set before success.
      const checked=await readSites();
      if(JSON.stringify(checked.data)!==JSON.stringify(normalized))
        throw Object.assign(Error('保存结果未知；不要再次覆盖，请重新打开核对'),{code:'E_OUTCOME_UNKNOWN'});
      reply={etag:checked.etag};
    }
    sites=normalized;sitesEtag=reply.etag;renderSites();
  }finally{siteBusy=false;report();}
}
function renderSites(){
  const host=el('ps-sites-list');host.replaceChildren();
  if(!sitesReady){host.append(dom('p','ps-hint','网站规则未加载。'));return;}
  if(!sites.rules.length)host.append(dom('p','ps-hint','目前仅启用内置 ChatGPT。'));
  for(const rule of sites.rules){
    const card=dom('article','ps-site-row');
    const head=dom('div','ps-site-row-heading');
    head.append(dom('strong','',rule.origin),dom('small','',rule.enabled?'已启用':'已停用'));
    const path=dom('small','ps-site-origin','路径：'+rule.pathScope);
    const actions=dom('div','ps-actions');
    button(actions,'编辑',()=>openSiteForm(rule));
    button(actions,rule.enabled?'停用':'启用',()=>void (async()=>{
      try{
        const next={schema:1,rules:sites.rules.map(entry=>siteKey(entry)===siteKey(rule)?
          {...entry,enabled:!entry.enabled}:entry)};
        await commitSites(next);siteMessage('网站启停设置已保存。');
      }catch(error){siteMessage('启停失败：'+(error.code||error.message),true);}
    })());
    if(siteDelete===siteKey(rule)){
      button(actions,'确认删除',()=>void (async()=>{
        try{await commitSites({schema:1,rules:sites.rules.filter(entry=>siteKey(entry)!==siteKey(rule))});
          siteDelete=null;renderSites();siteMessage('网站配置已删除。');
        }catch(error){siteMessage('删除未确认：'+(error.code||error.message),true);}
      })(),'danger');
      button(actions,'取消删除',()=>{siteDelete=null;renderSites();});
    }else button(actions,'删除',()=>{siteDelete=siteKey(rule);renderSites();},'danger');
    card.append(head,path,actions);host.append(card);
  }
}
function openSiteForm(rule){
  if(siteBusy)return;
  ++siteEpoch;siteSession=null;siteVerified=null;siteDiscardPending=false;
  siteEditing=rule?siteKey(rule):null;siteOrigin=rule?.origin||null;
  el('ps-site-form').hidden=false;
  el('ps-site-container').value=rule?.containerSelector||'';
  el('ps-site-editor').value=rule?.editorSelector||'';
  el('ps-site-path').value=rule?.pathScope||'/';
  el('ps-site-enabled').checked=rule?.enabled!==false;
  el('ps-site-origin').textContent=siteOrigin||'请选择当前网站';
  el('ps-site-form-title').textContent=rule?'编辑网站规则':'配置当前网站';
  el('ps-site-verified').textContent='保存前请在该网站测试定位。';
  siteBaseline=JSON.stringify(siteDraft());siteDirty=false;report();
  el('ps-site-container').focus();
}


async function openCurrentSite(){
  if(!sitesReady||siteBusy)return;
  if(siteDirty){siteMessage('请先保存或取消当前未保存的网站配置。',true);return;}
  try{
    const context=await request('prompt.page.context',{});
    if(context?.status!=='available'||!context.origin)throw Error('请先打开普通网页');
    if(context.origin==='https://chatgpt.com')throw Error('ChatGPT 已内置，无需重新配置');
    const matching=sites.rules.filter(rule=>rule.origin===context.origin&&
      (rule.pathScope==='/'||context.path===rule.pathScope||
      context.path.startsWith(rule.pathScope.endsWith('/')?rule.pathScope:rule.pathScope+'/')))
      .sort((a,b)=>b.pathScope.length-a.pathScope.length)[0];
    if(matching){openSiteForm(matching);return;}
    openSiteForm(null);siteOrigin=context.origin;
    el('ps-site-origin').textContent=context.origin;
    siteBaseline=JSON.stringify(siteDraft());siteDirty=false;report();
    siteMessage('请在网页上选择两个目标，然后测试并保存。');
  }catch(error){siteMessage(error.code||error.message,true);}
}
async function stopSitePick(){
  ++siteEpoch;clearTimeout(sitePoll);sitePoll=0;
  const session=siteSession;siteSession=null;
  if(session)try{await request('prompt.page.pick.cancel',{session});}catch{}
}
async function pickSite(kind){
  if(!siteOrigin||siteBusy||siteSession)return;
  const field=el(kind==='editor'?'ps-site-editor':'ps-site-container');
  const token=++siteEpoch;
  try{
    const current=await request('prompt.page.context',{});
    if(token!==siteEpoch)return;
    if(current?.origin!==siteOrigin)throw Error('请切换到 '+siteOrigin+' 的网页');
    const launched=await request('prompt.page.pick.start',{kind});
    if(token!==siteEpoch)return;
    if(launched?.state!=='selecting'||typeof launched.session!=='string')
      throw Error('网页未确认元素选择模式');
    siteSession=launched.session;siteMessage('请在网页中点击目标元素；按 Esc 可以取消。');
    let attempts=0;
    const poll=async()=>{
      if(token!==siteEpoch||!siteSession)return;
      try{
        const result=await request('prompt.page.pick.status',{session:siteSession});
        if(token!==siteEpoch)return;
        if(result?.state==='selected'){
          if(!model.validSelector(result.selector))throw Error('网页返回的选择器不符合规则');
          field.value=result.selector;
          siteSession=null;invalidateSite();
          siteMessage(kind==='editor'?'目标输入框已选取，请测试定位。':'按钮容器已选取，请继续选取输入框。');
          return;
        }
        if(result?.state!=='selecting'||++attempts>=64){
          siteSession=null;siteMessage('选取已取消、过期或网页已经切换。',true);return;
        }
        sitePoll=setTimeout(()=>void poll(),1000);
      }catch(error){
        if(token!==siteEpoch)return;
        siteSession=null;siteMessage('选取中断：'+(error.code||error.message),true);
      }
    };
    sitePoll=setTimeout(()=>void poll(),1000);
  }catch(error){if(token===siteEpoch)siteMessage('无法开始选择：'+(error.code||error.message),true);}
}
async function testSite(){
  if(!siteOrigin||siteBusy||siteSession)return;
  try{
    const rule=model.siteRule(siteDraft());
    siteMessage('正在当前网页验证两个目标…');
    const result=await request('prompt.page.check',{rule});
    if(result?.valid!==true||result.containerMatches!==1||result.editorMatches!==1||
       !['textarea','input','richtext'].includes(result.editorType))
      throw Error('网页未返回唯一、有效的选择器验证结果');
    siteVerified=JSON.stringify(rule);
    el('ps-site-verified').textContent='验证成功 · '+result.editorType+' · 容器和输入框均唯一匹配';
    siteMessage('定位检查通过；仅表示目标可定位，实际富文本插入仍需真实网站验收。');
  }catch(error){siteVerified=null;siteMessage('测试失败：'+(error.code||error.message),true);}
}
async function saveSite(){
  if(!siteOrigin||siteBusy||siteSession)return;
  let rule;
  try{
    rule=model.siteRule(siteDraft());
    if(siteVerified!==JSON.stringify(rule))throw Error('请先测试当前填写的两个选择器');
    if(siteEditing&&!sites.rules.some(row=>siteKey(row)===siteEditing))
      throw Error('旧网站规则已被修改，请重新读取');
    const next={schema:1,rules:siteEditing?
      sites.rules.map(row=>siteKey(row)===siteEditing?rule:row):[...sites.rules,rule]};
    await commitSites(next);
    siteEditing=null;siteOrigin=null;siteVerified=null;siteDirty=false;
    el('ps-site-form').hidden=true;report();siteMessage('网站配置已保存。刷新页面后将自动使用相同规则。');
  }catch(error){siteMessage('保存失败，配置仍保留在表单中：'+(error.code||error.message),true);}
}
async function cancelSiteForm(){
  if(siteDirty&&!siteDiscardPending){
    siteDiscardPending=true;
    siteMessage('存在未保存的网站配置。再次点击「取消」才会放弃；也可以继续编辑。',true);
    return;
  }
  await stopSitePick();siteDirty=false;siteOrigin=null;siteEditing=null;siteVerified=null;
  siteDiscardPending=false;el('ps-site-form').hidden=true;report();siteMessage('');
}
async function toggleSites(){
  const panel=el('ps-sites-panel'),open=panel.hidden;
  if(!open&&siteDirty){siteMessage('请先保存或明确取消未保存的网站配置。',true);return;}
  if(!open)await stopSitePick();
  panel.hidden=!open;el('ps-sites-open').setAttribute('aria-expanded',String(open));
  if(!open){sitesReady=false;return;}
  try{await loadSites();siteMessage('');}
  catch(error){sitesReady=false;renderSites();siteMessage('网站规则读取失败：'+(error.code||error.message),true);}
}

function render(){
  const list=el('ps-list');list.replaceChildren();
  const enabled=data.items.filter(item=>item.enabled).length;
  el('ps-count').textContent=data.items.length+' 个 · '+enabled+' 个启用';
  el('ps-empty').hidden=data.items.length>0;
  el('ps-web').checked=data.settings.webButtons;
  for(const [i,item] of data.items.entries()){
    const card=dom('article','ps-card'+(!item.enabled?' is-disabled':''));
    const mainRow=dom('div','ps-card-main');
    const glyph=dom('div','ps-glyph');
    glyph.setAttribute('aria-hidden','true');
    for(const char of model.parts(item.label))glyph.append(dom('span','',char));
    const use=button(mainRow,item.body,()=>void copy(item),'quiet');
    use.replaceChildren(dom('span','ps-card-preview',item.body));
    use.className='ps-card-use od-button od-button--quiet';use.dataset.locked=item.enabled?'0':'1';
    const description=item.nameAuto?model.auto(item.body):item.name||model.auto(item.body);
    use.setAttribute('aria-label',(item.enabled?'复制提示词：':'已停用的提示词：')+item.body.slice(0,90));
    use.title=item.enabled?'复制完整提示词；ChatGPT 网页左侧按钮可直接插入草稿':'该按钮已停用';
    const actions=dom('div','ps-card-actions');
    const edit=button(actions,'编辑',()=>start(item.id));
    edit.setAttribute('aria-label','编辑 '+description);
    const more=button(actions,'⋯',()=>{expanded=expanded===item.id?null:item.id;pendingDelete=null;render();});
    more.setAttribute('aria-label','更多操作：'+description);
    more.setAttribute('aria-expanded',String(expanded===item.id));
    mainRow.prepend(glyph);mainRow.append(actions);card.append(mainRow);
    if(!item.nameAuto&&item.name?.trim())card.append(dom('div','ps-card-caption',item.name));
    if(expanded===item.id){
      const commands=dom('div','ps-more');
      button(commands,item.enabled?'停用':'启用',()=>void update(item.id,row=>({...row,enabled:!row.enabled})));
      const up=button(commands,'↑ 上移',()=>void move(item.id,-1));up.dataset.locked=i===0?'1':'0';
      const down=button(commands,'↓ 下移',()=>void move(item.id,1));down.dataset.locked=i===data.items.length-1?'1':'0';
      button(commands,'删除',()=>{pendingDelete=item.id;render();
        root.querySelector('.ps-delete-cancel')?.focus();},'danger');
      card.append(commands);
    }
    if(pendingDelete===item.id){
      const confirm=dom('div','ps-confirm');
      confirm.append(dom('p','','确认删除「'+item.name+'」？此操作不能撤销。'));
      const buttons=dom('div','ps-actions');
      const cancel=button(buttons,'取消',()=>{pendingDelete=null;render();});
      cancel.classList.add('ps-delete-cancel');
      button(buttons,'确认删除',()=>void remove(),'danger');
      confirm.append(buttons);card.append(confirm);
    }
    list.append(card);
  }
  lock();
}
async function readLibrary(){
  const saved=await request('storage.get',{key:KEY,withEtag:true});
  if(!/^[0-9a-f]{64}$/.test(saved?.etag||''))throw Error('宿主未提供 ETag 并发保护');
  if(!Object.hasOwn(saved,'value'))throw Error('宿主未提供可核实的存储数据');
  return {value:model.load(saved.value),etag:saved.etag};
}
async function commit(next){
  if(unconfirmedWrite)throw Error('上次写入结果未确认，请先保留草稿并重新打开核对');
  if(!ready||busy)throw Error('工具暂不可写入');
  if(model.bytes(next)>8192)throw Object.assign(Error('提示词共用 8 KiB 数据项，超出存储上限'),{code:'E_TOOL_DATA_LIMIT'});
  busy=true;lock();
  try{
    let saved;
    try{
      saved=await request('storage.set',{key:KEY,value:next,ifMatch:etag});
      if(saved?.saved!==true||!/^[0-9a-f]{64}$/.test(saved.etag||''))throw Error('没有收到可核实的持久保存结果');
    }catch(e){
      if(['E_STORAGE_CONFLICT','E_TOOL_DATA_LIMIT'].includes(e.code))throw e;
      unconfirmedWrite=true;status('写入回执未确认，正在核对已保存数据…',true);
      try{
        const checked=await readLibrary();
        // Chrome Storage can reorder object keys. Confirm the entire intended library.
        const encode=value=>JSON.stringify(value,(_key,row)=>row&&typeof row==='object'&&!Array.isArray(row)
          ?Object.fromEntries(Object.keys(row).sort().map(key=>[key,row[key]])):row);
